package com.example.petstore

import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test

class ApiExceptionTest {
    @Test
    fun exposesStatusCodeMessageBodyHeadersErrorBody() {
        val ex =
            ApiException(
                statusCode = 404,
                message = "not found",
                responseHeaders = mapOf("content-type" to "application/json"),
                responseBody = "{\"id\":7,\"name\":\"missing\"}",
                errorBody = null,
            )

        assertEquals(404, ex.statusCode)
        assertEquals("{\"id\":7,\"name\":\"missing\"}", ex.responseBody)
        assertEquals("application/json", ex.responseHeaders?.get("content-type"))
        assertNull(ex.errorBody)
    }

    @Test
    fun nullHeadersAndBodyMarkTransportNoResponse() {
        // apierror-responsebody-headers-nullable-split: null is distinct from an
        // empty header map / empty body so a pre-response transport failure can
        // be encoded.
        val ex =
            ApiException(
                statusCode = 0,
                message = "connection reset",
                responseHeaders = null,
                responseBody = null,
            )

        assertNull(ex.responseHeaders)
        assertNull(ex.responseBody)
    }

    @Test
    fun isAnExceptionWithStatusInMessage() {
        val ex =
            ApiException(
                statusCode = 500,
                message = "boom",
                responseHeaders = null,
                responseBody = null,
            )

        assertTrue(ex is Exception)
        assertTrue(ex.message.contains("500"))
    }

    @Test
    fun getTypedErrorBodyReturnsTheTypedErrorBody() {
        val body =
            com.example.petstore.models
                .Category(id = 42L, name = "Dogs")
        val ex =
            ApiException(
                statusCode = 400,
                message = "bad request",
                responseHeaders = emptyMap(),
                responseBody = "{\"id\":42,\"name\":\"Dogs\"}",
                errorBody = body,
            )

        val typed = ex.getTypedErrorBody(com.example.petstore.models.Category::class.java)
        assertNotNull(typed)
        assertEquals(42L, typed!!.id)
        assertEquals("Dogs", typed.name)
    }

    @Test
    fun getTypedErrorBodyReturnsNullWhenNoErrorBody() {
        val ex =
            ApiException(
                statusCode = 500,
                message = "oops",
                responseHeaders = emptyMap(),
                responseBody = null,
                errorBody = null,
            )

        assertNull(ex.getTypedErrorBody(com.example.petstore.models.Category::class.java))
    }

    @Test
    fun getTypedErrorBodyReturnsNullForMismatchedType() {
        val ex =
            ApiException(
                statusCode = 422,
                message = "unprocessable",
                responseHeaders = emptyMap(),
                responseBody = null,
                errorBody = "not-a-category",
            )

        assertNull(ex.getTypedErrorBody(com.example.petstore.models.Category::class.java))
    }
}
